  db.execSQL("CREATE TABLE draws(issue TEXT PRIMARY KEY,open_time INTEGER,dirty INTEGER,n1 INT,n2 INT,n3 INT,n4 INT,n5 INT,n6 INT,n7 INT,n8 INT,n9 INT,n10 INT)");c.setAutoCommit(false);SchemaR27.ensureLiveSourceRevision(db);ResearchEvolutionStoreR930.createSchema(db);c.commit();c.setAutoCommit(true);
  ReplayDatasetR27 data=ReplayDatasetR27.synthetic(3000,30,new int[0]);FeatureCacheR27 cache=new FeatureCacheR27(data);EvalContextR27 ctx=new EvalContextR27(cache,SplitR27.of(data,null),null);PolicySpecR27 p=parent();PolicySpecR27 child=DirectedResearchPolicyR30R1.withoutChild(p,"root/0",0);
  ResearchContractR30R1 contract=new ResearchContractR30R1(data.datasetHash,p.policyHash(),FrozenConfirmationR30.currentSemantics(),com.ethk3.novaonepro.BuildConfig.SOURCE_COMMIT_R26,StatsR27.sha256("input"),ResearchContractR30R1.Role.SELECT,data.ordinals[ctx.split.selectFrom],data.ordinals[ctx.split.selectTo-1],0,0);
  ResearchGainR30R1 gain=new ResearchGainR30R1(contract.fromOrdinal,contract.throughOrdinal,64,4,200);for(long i=contract.fromOrdinal;i<=contract.throughOrdinal;i++)gain.add(i,.2,.3);ResearchGainR30R1.Estimate e=gain.estimate();ResearchAdviceR30R1 advice=ResearchAdviceR30R1.component(contract,"root/0",e,contract.throughOrdinal+1,1);check(advice.action==ResearchAdviceR30R1.Action.PRUNE_COMPONENT,"HOST_CONTROLLED_NEGATIVE_NOT_PRUNE");
  ResearchWriteQueueR27.Batch fail=ResearchStoreR30R1.paired(contract,e,advice,child.fullJson(),child.policyHash(),1);fail.add("INSERT INTO deliberate_missing_table VALUES(1)");try{tx(c,db,fail);throw new AssertionError("FAULT_NOT_INJECTED");}catch(RuntimeException expected){}check(count(db,"SELECT count(*) FROM r30r1_analysis_run")==0&&count(db,"SELECT count(*) FROM r30r1_research_measure")==0&&count(db,"SELECT count(*) FROM r30r1_proposal")==0&&count(db,"SELECT count(*) FROM r30r1_chart_cache")==0,"HALF_ANALYSIS_CHAIN");
