  String run=contract.key("PAIRED_COMPONENT_ANALYSIS_V1|"+e.analysisContractHash+'|'+advice.componentPath);Map<String,Object> summary=new LinkedHashMap<>();summary.put("sourceContract",PairedReplayRunnerR30R1.contractJson(contract));summary.put("parent",p.fullJson());ResearchWriteQueueR27.Batch metadata=new ResearchWriteQueueR27.Batch();metadata.add("UPDATE r30r1_analysis_run SET summary_json=? WHERE run_id=?",JsonR27.write(summary),run);tx(c,db,metadata);
  ResearchWriteQueueR27.Batch wrong=new ResearchWriteQueueR27.Batch();ResearchStoreR30R1.consume(wrong,advice.proposalId,p.policyHash(),0,"HOST",2);try{tx(c,db,wrong);throw new AssertionError("FOREIGN_CHILD_ACCEPTED");}catch(RuntimeException expected){}check(count(db,"SELECT count(*) FROM r30r1_consume")==0,"FOREIGN_CHILD_RECEIPT");
  EvolutionLoopR27.Config cfg=new EvolutionLoopR27.Config();cfg.births=1;cfg.minPerFamily=0;cfg.expertShare=0;cfg.nullControl=false;StoreR27.EvolutionSink sink=new StoreR27.EvolutionSink("HOST",data.issues[data.size()-1]);EvolutionLoopR27 loop=new EvolutionLoopR27(cfg,cache,sink,()->1);loop.step=2;loop.directedResearch=ResearchStoreR30R1.ready(db,ctx,0,4);check(loop.directedResearch.size()==1,"NO_ACTUAL_DIRECTED_INPUT");loop.step();loop.step();check("BORN".equals(loop.pendingState(child.policyHash())),"ORIGINAL_GATE_DID_NOT_ACCEPT_MEASURED_CHILD:"+loop.pendingState(child.policyHash()));loop.commitResearchAdmissions(sink.batch,3);sink.batch.add("INSERT OR REPLACE INTO r27_evolution_cursor VALUES('HOST',?,?,?,0,?,3)",loop.generation,loop.step,data.datasetHash,loop.snapshot());
